1	//! Geometry primitives for the Clipper2 re-implementation.
2	//!
3	//! Mirrors the parts of Clipper2Lib's core geometry types that the boolean
4	//! module needs: 64-bit integer points, path types, signed area, and
5	//! segment helpers. All orientation predicates use 128-bit integer
6	//! arithmetic so they are exact for `i64` coordinates.
7	
8	/// A point with 64-bit integer coordinates (Clipper2 `Point64`).
9	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
10	pub struct Point64 {
11	    pub x: i64,
12	    pub y: i64,
13	}
14	
15	impl Point64 {
16	    pub fn new(x: i64, y: i64) -> Self {
17	        Point64 { x, y }
18	    }
19	}
20	
21	/// A single polygon contour (Clipper2 `Path64`).
22	pub type Path64 = Vec<Point64>;
23	/// A set of polygon contours (Clipper2 `Paths64`).
24	pub type Paths64 = Vec<Path64>;
25	
26	/// Winding rule used when filling open/self-overlapping geometry.
27	/// The boolean module only needs to handle simple polygons, where all
28	/// rules agree, but the enum is part of the shared API contract.
29	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
30	pub enum FillRule {
31	    EvenOdd,
32	    NonZero,
33	    Positive,
34	    Negative,
35	}
36	
37	/// Signed area of a polygon; positive for counter-clockwise winding
38	/// (standard Cartesian y-up), matching Clipper2's `Area()`.
39	///
40	/// Uses the shoelace formula. The sum of cross products of `i64`
41	/// coordinates is accumulated in `i128`, so the result is exact
42	/// regardless of coordinate magnitude; it is returned as `f64` to
43	/// match Clipper2's API.
44	pub fn area(path: &Path64) -> f64 {
45	    let n = path.len();
46	    if n < 3 {
47	        return 0.0;
48	    }
49	    let mut acc: i128 = 0;
50	    for i in 0..n {
51	        let p = path[i];
52	        let q = path[(i + 1) % n];
53	        acc += p.x as i128 * q.y as i128 - q.x as i128 * p.y as i128;
54	    }
55	    acc as f64 / 2.0
56	}
57	
58	/// `true` iff the polygon winds counter-clockwise (`area(path) > 0`).
59	pub fn is_positive(path: &Path64) -> bool {
60	    area(path) > 0.0
61	}
62	
63	/// 128-bit cross product `(a - o) x (b - o)`; sign is positive iff
64	/// `o -> a -> b` is a left turn (counter-clockwise, y-up).
65	pub fn cross(o: Point64, a: Point64, b: Point64) -> i128 {
66	    (a.x as i128 - o.x as i128) * (b.y as i128 - o.y as i128)
67	        - (a.y as i128 - o.y as i128) * (b.x as i128 - o.x as i128)
68	}
69	
70	/// `true` iff `p` lies on the closed segment `a`-`b` (exact, integer test).
71	pub fn point_on_segment(p: Point64, a: Point64, b: Point64) -> bool {
72	    if cross(a, b, p) != 0 {
73	        return false;
74	    }
75	    // Collinear: check p is within the bounding box of the segment.
76	    p.x >= a.x.min(b.x)
77	        && p.x <= a.x.max(b.x)
78	        && p.y >= a.y.min(b.y)
79	        && p.y <= a.y.max(b.y)
80	}
81	
82	/// A segment intersection reported in floating point.
83	///
84	/// `t` (resp. `u`) is the parametric position along the first (resp.
85	/// second) segment: `point = p1 + t * (p2 - p1)`, with `t, u` in `[0, 1]`.
86	#[derive(Clone, Copy, PartialEq, Debug)]
87	pub struct SegIntersection {
88	    pub point: (f64, f64),
89	    pub t: f64,
90	    pub u: f64,
91	}
92	
93	/// Computes the proper intersection of segments `p1`-`p2` and `p3`-`p4`.
94	///
95	/// Returns `Some` when the segments are not parallel and the intersection
96	/// point lies on both segments (inclusive of endpoints). Collinear and
97	/// parallel segments return `None` (overlapping-collinear cases are a
98	/// degeneracy the boolean module skips rather than reports).
99	pub fn segment_intersection(
100	    p1: Point64,
101	    p2: Point64,
102	    p3: Point64,
103	    p4: Point64,
104	) -> Option<SegIntersection> {
105	    let d1x = (p2.x - p1.x) as f64;
106	    let d1y = (p2.y - p1.y) as f64;
107	    let d2x = (p4.x - p3.x) as f64;
108	    let d2y = (p4.y - p3.y) as f64;
109	    let denom = d1x * d2y - d1y * d2x;
110	    // Parallel (or a zero-length segment): no unique intersection.
111	    if denom.abs() < 1e-12 {
112	        return None;
113	    }
114	    let ex = (p3.x - p1.x) as f64;
115	    let ey = (p3.y - p1.y) as f64;
116	    let t = (ex * d2y - ey * d2x) / denom;
117	    let u = (ex * d1y - ey * d1x) / denom;
118	    const EPS: f64 = 1e-9;
119	    if t < -EPS || t > 1.0 + EPS || u < -EPS || u > 1.0 + EPS {
120	        return None;
121	    }
122	    let t = t.clamp(0.0, 1.0);
123	    let u = u.clamp(0.0, 1.0);
124	    Some(SegIntersection {
125	        point: (p1.x as f64 + t * d1x, p1.y as f64 + t * d1y),
126	        t,
127	        u,
128	    })
129	}
130	
131	/// Rounds a floating-point point to the integer grid, matching
132	/// Clipper2's round-to-nearest grid snapping of intersection vertices.
133	pub fn round_point(pt: (f64, f64)) -> Point64 {
134	    Point64::new(pt.0.round() as i64, pt.1.round() as i64)
135	}
136	
