142	        pts.iter().map(|&(x, y)| Point64::new(x, y)).collect()
143	    }
144	
145	    #[test]
146	    fn area_ccw_is_positive() {
147	        // Unit square wound CCW (y-up).
148	        let p = path(&[(0, 0), (1, 0), (1, 1), (0, 1)]);
149	        assert_eq!(area(&p), 1.0);
