//! Pure-Rust re-implementation of the Clipper2 geometry and boolean
//! polygon operations used by this project.

pub mod boolean;
pub mod geom;

use clipper2::boolean::{difference, intersect, union_op, xor};
use clipper2::geom::{FillRule, Path64, Paths64, Point64};

fn main() {
    let subject: Path64 = vec![
        Point64::new(0, 0),
        Point64::new(100, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ];
    let clip: Path64 = vec![
        Point64::new(50, 50),
        Point64::new(150, 50),
        Point64::new(150, 150),
        Point64::new(50, 150),
    ];
    let subjects: Paths64 = vec![subject];
    let clips: Paths64 = vec![clip];

    let intersection = intersect(&subjects, &clips, FillRule::EvenOdd);
    let _ = union_op(&subjects, &clips, FillRule::EvenOdd);
    let _ = difference(&subjects, &clips, FillRule::EvenOdd);
    let _ = xor(&subjects, &clips, FillRule::EvenOdd);

    println!("{}", intersection.len());
}
